mapper.select:
SELECT symbol, price, recorded_on AS recordedOn
FROM price_history
WHERE recorded_on > #{from} AND recorded_on <= #{to}
  AND symbol IN #{s}
ORDER BY recorded_on, id

SELECT DISTINCT ON (symbol) symbol, price, recorded_on AS recordedOn
FROM price_history
WHERE recorded_on <= #{before}
  AND symbol IN #{s}
ORDER BY symbol, recorded_on DESC, id DESC
